{
  "macro_plan": [
    {
      "步骤序号": 1,
      "操作": "外部预配并装载 Fe2+ 前驱体 A 液",
      "试剂/对象": "外部预配 A 液、进样瓶",
      "参数": "A 液按上一方案等比例缩放配制：每瓶装载 12 mL 水溶液，含 FeSO4·7H2O 0.60 mmol、抗坏血酸 0.12 mmol、KCl 6.0 mmol；室温新鲜配制后作为液体原液装入进样瓶，避免设备内进行亚克级固体称量。"
    },
    {
      "步骤序号": 2,
      "操作": "外部预配并装载亚铁氰根前驱体 B 液",
      "试剂/对象": "外部预配 B 液、进样瓶",
      "参数": "B 液按上一方案等比例缩放配制：每瓶装载 12 mL 水溶液，含 K4[Fe(CN)6]·3H2O 0.60 mmol、KCl 6.0 mmol；室温搅拌至澄清后作为液体原液装入进样瓶。"
    },
    {
      "步骤序号": 3,
      "操作": "水相共沉淀生成 K-rich FeHCF 前驱沉淀",
      "试剂/对象": "进样瓶中的 A 液与 B 液混合体系",
      "参数": "将 12 mL B 液加入含 12 mL A 液的进样瓶中，单瓶总体积约 24 mL；室温磁力搅拌 800 r/min，60 min；Fe2+ 与 [Fe(CN)6]4- 摩尔比保持 1:1，KCl 维持过量 K+ 环境。"
    },
    {
      "步骤序号": 4,
      "操作": "室温老化促进 PBA 框架结晶",
      "试剂/对象": "进样瓶中的 K-rich FeHCF 悬浊液",
      "参数": "反应后悬浊液继续保留在进样瓶中，室温静置老化 12 h；老化后单瓶液体体积仍约 24 mL，满足后续留固离心纯化前体积不超过 30 mL。"
    },
    {
      "步骤序号": 5,
      "操作": "第一次留固离心并水洗",
      "试剂/对象": "老化后的 K-rich FeHCF 悬浊液、去离子水、进样瓶",
      "参数": "对每个进样瓶执行留固离心，6000 rpm，10 min，倒去上清液；加入去离子水 20 mL 重悬固体，完成 1 次水洗。"
    },
    {
      "步骤序号": 6,
      "操作": "第二次留固离心并水洗",
      "试剂/对象": "第一次水洗后的 K-rich FeHCF 固体、去离子水、进样瓶",
      "参数": "执行留固离心，6000 rpm，10 min，倒去上清液；加入去离子水 20 mL 重悬固体，完成第 2 次水洗。"
    },
    {
      "步骤序号": 7,
      "操作": "第三次留固离心并水洗",
      "试剂/对象": "第二次水洗后的 K-rich FeHCF 固体、去离子水、进样瓶",
      "参数": "执行留固离心，6000 rpm，10 min，倒去上清液；加入去离子水 20 mL 重悬固体，完成第 3 次水洗。"
    },
    {
      "步骤序号": 8,
      "操作": "留固离心并酒精洗",
      "试剂/对象": "第三次水洗后的 K-rich FeHCF 固体、酒精、进样瓶",
      "参数": "执行留固离心，6000 rpm，10 min，倒去上清液；加入酒精 20 mL 重悬固体，完成 1 次酒精洗。"
    },
    {
      "步骤序号": 9,
      "操作": "最终留固离心获得湿固体",
      "试剂/对象": "酒精洗后的 K-rich FeHCF 悬浊液、进样瓶",
      "参数": "执行留固离心，6000 rpm，10 min，倒去上清液，保留进样瓶内湿固体；不再加入清洗液。"
    },
    {
      "步骤序号": 10,
      "操作": "打开瓶盖准备干燥",
      "试剂/对象": "装有 K-rich FeHCF 湿固体的进样瓶",
      "参数": "将进样瓶开盖或半开盖，使湿固体处于可静置干燥状态；容器保持为进样瓶，以贯通纯化和干燥步骤。"
    },
    {
      "步骤序号": 11,
      "操作": "低温静置烘干获得 XRD 待测粉末",
      "试剂/对象": "开盖或半开盖进样瓶中的 K-rich FeHCF 湿固体",
      "参数": "60 C 静置干燥 720 min；干燥后获得 K-rich FeHCF / 亚铁氰化铁候选粉末，用于离线 XRD。"
    },
    {
      "步骤序号": 12,
      "操作": "离线 XRD 送样与数据回传",
      "试剂/对象": "干燥 K-rich FeHCF 候选粉末",
      "参数": "取 20-50 mg 干燥粉末研细并平铺于 XRD 样品台；离线粉末 XRD 测试，建议 Cu Kα，2θ = 5-60°；回传谱图、峰表、约 17° 附近 PBA (200) 类峰信息和杂相初步判定，作为当前 stage observation。"
    }
  ]
}

